import fs from 'fs';
import path from 'path';

// Script to generate the comprehensive 235 West African & Sahelian crop technical sheets dataset
// Focused primarily on Burkina Faso priority crops and regional West African crops

const crops = [];

function add(category, id, key, name, sci, bf, origin, reg, cMin, cMax, zones, sea, npk, water, yld, vars, pests, diss, notes, icon) {
  crops.push({
    id: `sheet-${id}`,
    crop_key: key,
    name_fr: `${name} (${sci})`,
    scientific_name: sci,
    category: category,
    is_burkina_priority: !!bf,
    country_origin: bf ? "Burkina Faso (Prioritaire)" : (origin || "Afrique de l'Ouest / CEDEAO"),
    regions_burkina: reg || ["Hauts-Bassins", "Cascades", "Boucle du Mouhoun"],
    cycle_days_min: cMin,
    cycle_days_max: cMax,
    climate_zones: zones,
    seasons: sea,
    npk_needs: npk,
    water_needs_mm: water,
    common_pests: pests,
    common_diseases: diss,
    recommended_varieties: vars,
    yield_potential_t_ha: yld,
    notes: notes,
    iconName: icon || "sprout"
  });
}

